// Üretilen dosya: tool/ozgun/uret.py. Edebiyat · Edebî terimler, anlatıcı, bakış açısı ve metin çözümleme (zor).
const ozLiterature14Zor = <(String, String, List<String>, String)>[
  ('Tezat ile antitez arasındaki ilişkiyi en iyi hangisi açıklar?', 'Tezat sözcük düzeyinde karşıtlık, antitez düşünce düzeyinde karşıtlıktır.', ['Tezat yalnız şiirde, antitez yalnız romanda bulunur.', 'Tezat abartma, antitez benzetme amacıyla yapılır.', 'Tezatta anlam çelişir, antitezde çelişmez.'], 'Tezat zıt sözcüklerin, antitez ise karşıt yargıların yan yana getirilmesidir.'),
  ('Bir öğrenci \'Kalabalıkta yalnızım.\' sözünün paradoks olduğunu söylüyor. Bu yorumun gerekçesi aşağıdakilerden hangisi olmalıdır?', 'Yalnızlık ile kalabalık kavramları görünüşte çelişir ama anlamlı bir duyguyu anlatır.', ['Sözün içinde bir benzetme edatı bulunmaktadır.', 'Söz, gerçeklikten çok uzak ve abartılıdır.', 'Bir sözcük iki ayrı anlamda kullanılmıştır.'], 'Paradoksta çelişki yüzeydedir ve derinde bir doğru ya da duygu taşır.'),
  ('\'Yaşamak için ölmek gerekir bazen.\' cümlesinin paradoks sayılması aşağıdakilerden hangisine dayanır?', 'Çelişkili görünen iki kavramın anlamlı bir gerçeği sezdirmesine', ['Ölüm kavramının bir canlı gibi konuşturulmasına', 'Aynı sözün iki ayrı anlamda tekrar edilmesine', 'Dizeler arasında uyak bulunmasına'], 'Yaşamak ile ölmek karşıt görünür; sözün gizli anlamı fedakârlığı sezdirir.'),
  ('Aşağıdaki ifadelerin hangisinde hem karşıtlık hem de yan yana kullanım vardır, ancak oksimoron yoktur?', 'Yazın sıcağı, kışın soğuğu bir ömre bedeldi.', ['Parlak karanlık', 'Acı bal', 'Yüksek alçakgönüllülük'], 'Diğerlerinde tek ifade içinde çelişen iki sözcük birleşirken, ilkinde karşıtlar ayrı sözlerdir.'),
  ('Alegori ile sembol arasındaki temel fark nedir?', 'Alegoride eserin bütünü ikinci bir anlamı taşır; sembol ise tek bir öğenin simgesel kullanımıdır.', ['Alegori yalnız şiirde, sembol yalnız romanda kullanılır.', 'Sembolde anlam tek ve kesindir, alegoride sonsuzdur.', 'Alegori kısa sözlerle, sembol uzun anlatımlarla yapılır.'], 'Alegori anlatının tümünü kapsayan bir benzetme sistemidir; sembol tek bir imgedir.'),
  ('Saussure\'ün göstergebilimine göre bir göstergenin ses ya da yazı biçimine, yani \'ev\' sözcüğünün sesleri ya da harflerine ne ad verilir?', 'Gösteren', ['Gösterilen', 'Gönderge', 'Karine'], 'Gösteren göstergenin biçim yüzü, gösterilen ise zihindeki kavramdır.'),
  ('Bir anlatıdaki \'deniz\' imgesi, bir bölümde özgürlüğü, başka bir bölümde ölümü çağrıştırıyorsa bu durum için hangisi söylenebilir?', 'İmge çok katmanlı bir sembol işlevi görmektedir.', ['Anlatıcı güvenilmez ve taraflı bir anlatıcıdır.', 'Metinde zaman geriye dönüşlerle kurulmuştur.', 'Deniz sözcüğü terim anlamıyla kullanılmıştır.'], 'Aynı imgenin birden çok anlamı çağrıştırması simgesel çok katmanlılığı gösterir.'),
  ('İmge ile benzetme arasındaki ilişki için aşağıdakilerden hangisi doğrudur?', 'İmge okurun zihninde duyusal bir canlandırma yaratır; benzetme bu canlandırmanın araçlarından biri olabilir.', ['İmge yalnız benzetme edatlı ifadelerde bulunur.', 'Benzetme imgenin zıddı olan bir kavramdır.', 'İmge yalnız gözle görülen şeyleri kapsar.'], 'İmgeler benzetme, istiare ya da doğrudan betimlemeyle kurulabilir ve her duyuya seslenebilir.'),
  ('Farklı şairlerin \'dünya bir han, ömür bir kervan\' gibi kalıplaşmış düşünceleri çeşitli biçimlerde yinelemesi hangi kavramla açıklanır?', 'Topos', ['Aliterasyon', 'Tevriye', 'Ellips'], 'Topos, bir edebî gelenekte ortak biçimde tekrarlanan kalıplaşmış tema ya da anlatım kalıbıdır.'),
  ('Bir romanda kahramanın bütün bölümlerde bir köprüyü geçmesi ve her seferinde bir şeyin değişmesi, yazarın bu kez hangi anlatım tekniğini kullandığını gösterir?', 'Yinelenen bir motifle dönüşümü vurgulamayı', ['Güvenilmez anlatıcıyı', 'Gözlemci bakış açısını', 'Geriye dönüş tekniğini'], 'Aynı sahnenin değişen biçimlerle yinelenmesi motifle dönüşümü gösterme tekniğidir.'),
  ('Bir dizede \'kuru\' sözcüğü hem gerçek anlamda (susuz) hem de \'gönlü hiçbir şey hissetmeyen\' anlamında kastediliyorsa bu sözcüğün kullanımı için hangisi söylenebilir?', 'Hem gerçek hem mecaz katmanlı bir kullanım yapılmıştır.', ['Sözcük yalnızca terim anlamlı kullanılmıştır.', 'Sözcük yalnızca gerçek anlamlıdır.', 'Cümlede deyim kullanılmıştır.'], 'Çok katmanlı anlam, sözcüğün aynı anda birden fazla anlamı çağrıştırmasıdır.'),
  ('Bir paragrafta yalnız örnekler ve ayrıntılar veriliyor, yazarın yargısı hiç belirtilmiyor. Bu paragraf için aşağıdakilerden hangisi söylenir?', 'Ana düşünce örtük olarak okurun çıkarımına bırakılmıştır.', ['Metin ana düşünceden tamamen yoksundur ve yalnız örnekten oluşur.', 'Metin yalnızca bir betimlemedir ve hiç yargı içermez.', 'Metin bilimsel bir makaledir.'], 'Ana düşünce açıkça yazılmamışsa da örneklerden çıkarılabilir; dolaylı anlatımda böyle olur.'),
  ('\'Doğa sevgisi\' teması işleyen iki metinden biri doğayı koruma gerekliliğini, diğeri doğanın insana huzur verdiğini öne çıkarıyor. Bu iki metin için hangisi doğrudur?', 'Temaları aynı, ana düşünceleri farklıdır.', ['Temaları ve ana düşünceleri aynıdır, çünkü konu aynıdır.', 'Temaları farklı, konuları aynıdır ve yargıları çelişir.', 'İkisi de yardımcı düşünceden oluşur.'], 'Aynı tema üzerinde farklı yargılar farklı ana düşünceler doğurur.'),
  ('Bir anlatıcı sık sık kendi sözleriyle çelişiyor, olayları kendi lehine yorumluyor ve başka kişilerce yalanlanıyor. Bu durumda hangi ölçütle değerlendirme yapılır?', 'Anlatıcının güvenilirliği', ['Olay örgüsünün sıkı çatışma yapısı', 'Mekânın gerçekliği', 'Zamanın kronolojisi'], 'Çelişki ve çıkar gözetme, anlatıcının güvenilmez olabileceğine dair ipuçlarıdır.'),
  ('Bir öyküde \'yazar\'ın sesini taşıyan ama kurmacanın içinde yer almayan, bütün öyküyü kurgulayan ve değerleri belirleyen\' zihinsel kurguya hangi ad verilir?', 'İma edilen yazar', ['Kahraman anlatıcı', 'Okur', 'Tanık'], 'Metnin değerlerini belirleyen ve gerçek yazardan ayırt edilen soyut kurguya ima edilen yazar denir.'),
  ('Bir öğrenci \'Anlatıcı güvenilmezse eser başarısızdır.\' diyor. Bu yargıyla ilgili en doğru değerlendirme hangisidir?', 'Yanlıştır; güvenilmez anlatıcı bilinçli bir sanat tercihi olabilir.', ['Doğrudur; her anlatıcı güvenilir olmalıdır.', 'Doğrudur; güvenilmez anlatıcı yalnızca dedektif romanında bulunur.', 'Yanlıştır; güvenilmez anlatıcı yalnızca şiirde bulunur.'], 'Güvenilmez anlatıcı, okuru yorum yapmaya iten bilinçli bir teknik olabilir.'),
  ('Genette\'in anlatı kuramında anlatıcının kahramandan daha fazlasını bildiği, her şeyi gören anlatıma ne ad verilir?', 'Sıfır odaklama', ['İçsel odaklama', 'Dışsal odaklama', 'Çoğul odaklama'], 'Anlatıcının kahramandan fazlasını bildiği anlatıma sıfır odaklama denir.'),
  ('Genette\'e göre anlatıcının yalnızca bir kahramanın bildikleriyle sınırlı kaldığı odaklamaya ne ad verilir?', 'İçsel odaklama', ['Sıfır odaklama', 'Dışsal odaklama', 'Üst odaklama'], 'Anlatı bir kahramanın bilgisine bağlıysa içsel odaklama vardır.'),
  ('Genette\'e göre anlatıcının kahramanlardan daha az bildiği, yalnız dışarıdan gördüklerini aktardığı odaklamaya ne denir?', 'Dışsal odaklama', ['Sıfır odaklama, her şeyi bilen anlatıcı', 'İçsel odaklama', 'Çoğul odaklama'], 'Anlatıcı dıştan bakıyor ve içlerini bilmiyorsa dışsal odaklama vardır.'),
  ('Bakış açısının bölüm ortasında bir anda değişmesi anlatı kuramında hangi sonucu doğurabilir?', 'Okurun kafasının karışması ya da özel bir etki yaratılması', ['Anlatıcının otomatik olarak güvenilir hâle gelmesi', 'Olayın çatışmasının çözülmesi', 'Metnin türünün destana dönüşmesi'], 'Tutarsız geçişler karışıklık yaratabilir; ustaca yapıldığında özel etki sağlar.'),
  ('Anlatıda bir olay anlatılırken zamanın durup yalnızca bir mekânın ya da kişinin betimlenmesine ayrılan bölüme anlatı kuramında ne denir?', 'Duraklama', ['Zaman atlaması', 'Özet', 'Tekrar'], 'Olay akışının betimleme ile durmasına duraklama denir.'),
  ('Hikâye zamanı ile anlatı zamanı arasındaki fark hangi seçenekte doğru verilmiştir?', 'Hikâye zamanı olayların geçtiği süredir; anlatı zamanı onların anlatılma sırası ve süresidir.', ['İkisi aynı kavramdır ve her zaman birbirine eşittir.', 'Anlatı zamanı olayların gerçek süresi, hikâye zamanı okuma süresidir.', 'Hikâye zamanı yalnız şiirde, anlatı zamanı yalnız romanda vardır.'], 'Olayların kendi süresi hikâye zamanıdır; anlatıda sunuluş düzeni ve süresi anlatı zamanıdır.'),
  ('Bir öyküde kahramanın tek bir saniyelik düşüş anı üç sayfa boyunca uzun uzun anlatılıyor. Bu zaman kullanımının etkisi nedir?', 'Anın yoğunluğunu ve gerilimi artırmak', ['Olayların hızla ve sorunsuzca ilerlemesini sağlamak', 'Anlatıcıyı güvenilmez kılmak', 'Olay örgüsünü kronolojik yapmak'], 'Kısa bir anın uzun anlatılması anı yavaşlatarak yoğunlaştırır.'),
  ('Bir öyküde başlangıçta aydınlık ve kalabalık olan ev, öykü ilerledikçe karanlık ve boşalmış bir yere dönüşüyor. Bu mekân değişiminin işlevi nedir?', 'Kişilerin yıkımını ve kaybını sezdirmek', ['Anlatıcıyı gizlemek', 'Kronolojiyi bozmak', 'Zamanı belirsiz kılmak'], 'Mekândaki bu dönüşüm, kişilerin yaşadığı çöküşü yansıtır.'),
  ('Mekân betimlemesinin kimi romanlarda uzun tutulmasının yaygın gerekçesi aşağıdakilerden hangisi değildir?', 'Kronolojik sıralamanın düzeltilmesi', ['Gerçeklik izlenimi yaratmak', 'Kişilerin iç dünyasını dolaylı biçimde yansıtmak', 'Atmosferi kurmak ve ruhsal havayı güçlendirmek'], 'Betimlemenin işlevi zaman sırasını düzeltmek değildir; diğer üçü mekân betimlemesinin işlevleridir.'),
  ('Bir anlatıda olayların tesadüflerle çözülmesi, çoğu eleştirmence neden eleştirilir?', 'İnandırıcılığı zayıflattığı için', ['Anlatıcıyı güvenilir kıldığı için', 'Zamanı dondurduğu için', 'Mekânı daralttığı için'], 'Nedensellik yerine rastlantı olay örgüsünün inandırıcılığını azaltır.'),
  ('\'Kapıyı açtı. Nasıl da yorgundu! Şimdi yatsa mıydı, yoksa önce mektubu mu yazsaydı? Zaten anlatacak ne vardı ki...\' parçasındaki anlatıcı sesi, kahramanın düşünceleriyle iç içe geçmiştir. Bu anlatım tekniğine ne ad verilir?', 'Serbest dolaylı anlatım', ['Anlatıcının her şeyi baştan sona dışarıdan nesnel biçimde özetlemesi', 'Kahramanın karşısındaki kişiyle karşılıklı konuştuğu açık diyalog', 'Anlatıcının okura doğrudan seslendiği müdahale tekniği'], 'Anlatıcının sesi ile kahramanın düşüncesi tırnaksız biçimde kaynaşmıştır.'),
  ('Bir romandaki kahramanın zihninden geçen \'Acaba şimdi arasam mı? Yoo, yok.\' gibi çıkarımları doğrudan aktaran teknik için aşağıdakilerden hangisi uygun bir ad değildir?', 'Çerçeve öykü', ['İç monolog', 'Bilinç akışı', 'Düşünce aktarımı'], 'Çerçeve öykü, bir anlatının başka bir anlatıyı kuşatmasıdır; diğerleri kahramanın düşüncesini aktarma biçimleridir.'),
  ('Üstkurmacanın bir roman üzerindeki en belirgin etkisi hangisidir?', 'Okuru kurmaca olduğunu hatırlatarak sorgulamaya çağırması', ['Okuru olayların gerçek olduğuna ikna etmesi', 'Anlatıcıyı ortadan kaldırması', 'Metni bilimsel yazıya dönüştürmesi'], 'Üstkurmaca kurgunun yapaylığını açığa çıkarır.'),
  ('Bir paragrafta bir cümle çıkarıldığında anlam bütünlüğü bozulmuyorsa bu cümle için aşağıdakilerden hangisi söylenebilir?', 'Konudan sapma ya da gereksiz bir cümle olabilir.', ['Paragrafın ana düşüncesidir.', 'Paragrafın tek giriş cümlesidir.', 'Paragrafın sonucudur.'], 'Çıkarılınca anlam bozulmayan cümle, anlatım bütünlüğüne zorunlu bir katkı sağlamıyordur.'),
  ('Öznel ve nesnel anlatım yargıları bir eleştiri yazısında nasıl bir arada kullanılır?', 'Eleştirmen kanıtlanabilir bilgilerle kendi yorumunu birlikte sunar.', ['Eleştirmen yalnız nesnel bilgilerle sınırlıdır.', 'Eleştirmen yalnız duygu belirtir.', 'İkisi birlikte kullanılamaz.'], 'İyi bir eleştiri, olgulara dayanan yorumlar içerir.'),
  ('Roman Jakobson\'a göre dilin, konuşanın duygusunu dile getirdiği işleve ne ad verilir?', 'Heyecan (duygusal) işlevi', ['Göndergesel işlev, bilgi aktarma', 'Alıcıyı etkileme işlevi, emir ve rica', 'Şiirsel işlev, biçimin öne çıkması'], 'Duyguyu yansıtan dil işlevi heyecan işlevidir.'),
  ('Jakobson\'un sınıflamasında \'Su kaynama noktasına 100 derecede ulaşır\' cümlesi dilin hangi işlevini taşır?', 'Göndergesel işlev', ['Şiirsel işlev', 'Heyecan işlevi', 'Alıcıyı etkileme işlevi'], 'Gerçek dünyaya ilişkin bilgi veren dil göndergesel işlevdedir.'),
  ('\'Hadi, kalk artık!\' cümlesi Jakobson\'a göre hangi işlevi taşır?', 'Alıcıyı etkileme (çağrı) işlevi', ['Göndergesel işlev', 'Şiirsel işlev', 'Üstdil işlevi'], 'Alıcıyı bir eyleme yönelten dil çağrı işlevidir.'),
  ('\'Alo, beni duyuyor musunuz?\' sözü Jakobson\'un hangi işlevini örnekler?', 'İlgi kurma (kanal) işlevi', ['Heyecan işlevi, konuşanın duygusunu dile getirme', 'Şiirsel işlev, mesajın biçimini öne çıkarma', 'Göndergesel işlev, olgusal bilgi verme'], 'İletişim kanalının açık olup olmadığını sınayan söz ilgi kurma işlevindedir.'),
  ('\'Mecaz\' sözcüğünün ne anlama geldiğini açıklayan bir cümle, dilin hangi işlevini yerine getirir?', 'Üstdil işlevi', ['Göndergesel işlev', 'Heyecan işlevi', 'Çağrı işlevi'], 'Dil hakkında konuşan dil üstdil işlevidir.'),
  ('Oyun metninde sahne düzenini, oyuncuların hareketlerini ve davranış biçimlerini belirten, parantez içinde ya da italik yazılan açıklamalara ne ad verilir?', 'Didaskali', ['Replik, oyuncunun söylediği sözler', 'Tirat, uzun konuşma bölümü', 'Aparte, seyirciye söylenen gizli söz'], 'Oyun yazarının sahne yönergeleri didaskalidir.'),
  ('Sahnede oyuncuların yerleşimi, hareketleri, dekor ve ışık düzeninin yönetmence belirlenmesine ne ad verilir?', 'Mizansen', ['Didaskali, yazarın sahne yönergeleri', 'Aparte, seyirciye gizli söz', 'Tirat, uzun konuşma'], 'Sahne düzenini belirleyen yönetmen çalışması mizansendir.'),
  ('Tiyatroda \'dördüncü duvar\' kavramı neyi ifade eder?', 'Oyuncu ile seyirci arasındaki görünmez ayrım', ['Sahnenin arka duvarını', 'Dekordaki kapı', 'Işık düzenini'], 'Dördüncü duvar, seyircinin olup bitene dışarıdan bakan konumunu ifade eden sanal çizgidir.'),
  ('Aristoteles\'e göre trajedinin izleyicide uyandırdığı korku ve acıma duygularının boşalımıyla ruhsal arınmayı sağlaması hangi terimle adlandırılır?', 'Katarsis', ['Mimesis, taklit', 'Hamartia, trajik kusur', 'Peripeteia, tersine dönüş'], 'Duygusal boşalım ve arınma katarsistir.'),
  ('Aristoteles\'in \'Poetika\' adlı eserinde tragedyayı tanımlarken hangi unsuru en önemli sayar?', 'Olay örgüsü', ['Dekor, sahne düzenini belirleyen görsel unsur', 'Kostüm, oyuncuların giysileri ve görünümü', 'Müzik, oyuna eşlik eden ses düzeni'], 'Aristoteles trajedinin ruhu olarak olay örgüsünü (mythos) görür.'),
  ('Trajik kahramanın yüksek mevkideki bir kişi olması klasik drama kuramında hangi sonuca yol açar?', 'Düşüşün daha etkileyici olması', ['Olayın komik olması', 'Olayın komik bir hâl alması ve gülme duygusu', 'Aparte kullanılmaması'], 'Yüksek konumdan düşüş korku ve acıma duygusunu güçlendirir.'),
  ('Freytag piramidine göre bir dramatik yapı hangi sırayla ilerler?', 'Serim, yükselme, doruk, düşüş, çözüm', ['Doruk, serim, yükselme, çözüm, düşüş ve sonuç', 'Çözüm, doruk, serim, yükselme, düşüş', 'Yükselme, serim, çözüm, doruk, düşüş'], 'Freytag\'a göre dramatik yapı serim, yükselme, doruk, düşüş ve çözüm basamaklarından oluşur.'),
  ('Karanlık şatolar, hayaletler ve ürpertici atmosferle kurulu romanlar için kullanılan tür adı hangisidir?', 'Gotik roman', ['Tarihî roman, geçmiş olaylara dayalı eser', 'Köy romanı, kırsal yaşamı işleyen eser', 'Bilimkurgu, gelecek teknolojisine dayalı eser'], 'Korku ve ürperti içeren, gizemli mekânlarda geçen roman gotik romandır.'),
  ('Nükteli söz ile espri arasındaki ilişki hangi seçenekte en doğru verilmiştir?', 'Nükte düşündüren zekice bir söz, espri ise çoğu zaman anlık güldürücü bir sözdür.', ['Nükte ve espri tamamen aynı anlamdadır.', 'Espri yalnız yazıda bulunur.', 'Nükte yalnız çocuklara özgüdür.'], 'Nükte ince bir düşünce taşırken espri anlık güldürmeye yöneliktir.'),
  ('Bir mizah yazarının bir toplumsal sorunu doğrudan eleştirmek yerine alayla göstermesinin nedeni aşağıdakilerden hangisi olabilir?', 'Eleştiriyi daha etkili ve baskıdan uzak biçimde sunmak', ['Metni uzatmak', 'Olay örgüsünü bozmak', 'Zamanı bulanıklaştırmak'], 'Gülmece, eleştiriyi yumuşatarak ve daha etkili hâle getirerek sunar.'),
  ('Metinlerarası bir gönderme okur tarafından fark edilmezse metin için hangisi söylenebilir?', 'Anlam yine de anlaşılır ama bir katman kaçırılmış olur.', ['Metin tamamen anlaşılmaz olur.', 'Metin kurmaca olmaktan çıkar.', 'Metin bilimsel olur.'], 'Gönderme fark edilmese de metnin yüzey anlamı korunur; ancak ek anlam katmanı kaybolur.'),
  ('Aruz ölçüsünde bir hecenin uzun ya da kısa sayılması neye bağlıdır?', 'Hecenin yapısına ve ünlünün uzunluğuna', ['Hecedeki ünsüz sayısının tek ya da çift olmasına', 'Sözcüğün kaç harfli olduğuna', 'Dizenin kaçıncı sırada olduğuna'], 'Aruzda hece uzun ya da kısa sayılırken hece yapısı ve ünlü uzunluğu belirleyicidir.'),
  ('Aruzda \'gül\' sözcüğündeki hece genellikle nasıl sayılır?', 'Uzun', ['Kısa (açık hece), ünlüyle biten hece', 'Ölçüye girmez', 'Hem kısa hem uzun'], 'Ünsüzle biten kapalı hece aruzda uzun sayılır.'),
  ('Aynı sayıda hece içeren iki dizenin okunuşta farklı ritim taşıması hangi unsurla açıklanır?', 'Durak ve vurgu düzeninin farklı olmasıyla', ['Dizenin kafiye taşımasıyla', 'Uyak düzeniyle', 'Başlıkla'], 'Aynı hece sayısına sahip dizeler duraklarına göre farklı akış kazanabilir.'),
  ('\'Gökyüzünde bulutlar dağılıyor\' dizesi ile \'Yaz akşamı bahçemizde oturduk\' dizesinin hece sayıları için aşağıdakilerden hangisi doğrudur?', 'İkisi de on bir hecelidir.', ['Birincisi on, ikincisi on bir hecelidir.', 'İkisi de on hecelidir.', 'Birincisi on iki, ikincisi on bir hecelidir.'], 'Her iki dizede on bir hece vardır.'),
  ('Şiirde ahenk sağlayan uyak ve redifin her ikisi de kaldırılırsa şiirde ağırlıklı olarak hangi unsur ahengi sağlar?', 'İç ritim ve ses tekrarları', ['Kronolojik düzen', 'Çatışma yapısı', 'Anlatıcı sesi'], 'Uyak ve redif yoksa ahenk iç ritim, aliterasyon ve asonansla sağlanır.'),
  ('Ahenk unsurları arasında aşağıdakilerden hangisi sayılmaz?', 'Olay örgüsü', ['Uyak, dize sonlarındaki ses benzerliği düzeni', 'Aliterasyon', 'Nakarat'], 'Olay örgüsü anlatıya özgü bir öğedir; diğerleri şiirde ses ve ritim düzenine aittir.'),
  ('Ahenk ile anlam arasındaki ilişkiye dair hangisi söylenebilir?', 'İyi bir şiirde ses düzeni anlamı desteklemelidir.', ['Ahenk anlamdan bağımsızdır.', 'Anlam ahenkten önemsizdir.', 'Ahenk yalnız ölçüyle ilgilidir.'], 'Ses düzeni anlamı güçlendirdiğinde şiirin etkisi artar.'),
  ('Methiye türünün bir kişiyi yüceltmesi, hicvin ise bir kişiyi ya da durumu yermesi bu türleri hangi bakımdan birbirinin karşıtı yapar?', 'Değer yargısı yönünden', ['Zaman yönünden, geçmiş ve gelecek ayrımı bakımından', 'Ölçü yönünden, hece sayısı bakımından', 'Mekân yönünden, anlatıldığı yer bakımından'], 'Methiye över, hiciv yerer; ikisi değer yargısı bakımından zıttır.'),
  ('Aynı konuyu hem lirik hem epik biçimde işleyen iki şairin yaklaşımı için en uygun yargı hangisidir?', 'Biri duygusal, diğeri olay anlatmaya dayalı yaklaşımla ele almıştır.', ['İkisi aynı tür ürün vermiştir.', 'İkisi de yalnız nesirle yazmıştır.', 'İkisi de didaktiktir.'], 'Lirik duyguya, epik olaya yönelir.'),
  ('Şiirde noktalama işaretlerinin hiç kullanılmaması hangi etkiyi doğurabilir?', 'Okuyucunun yorumuna ve akışa açık bir ritim', ['Şiirin ölçüsünün bozulması', 'Anlatıcının değişmesi', 'Uyağın kalkması'], 'Noktalamasız yazım okura kendi duraklarını belirleme özgürlüğü verir.'),
  ('Camus\'nün \'Sisifos Söyleni\'nde işlediği, insanın anlam arayışı ile evrenin sessizliği arasındaki çatışmayı adlandıran kavram hangisidir?', 'Absürt', ['Tragedya, yüce acıklı olay anlayışı', 'Pastoral, kır yaşamı tasviri', 'Satir, alaycı eleştiri'], 'Camus, insanın anlam isteği ile evrenin kayıtsızlığı arasındaki uyumsuzluğa absürt der.'),
  ('\'Anlık izlenimleri yakalama\' amacı güden ve adını Monet\'nin \'İzlenim, Gün Doğumu\' tablosundan alan sanat akımı hangisidir?', 'Empresyonizm', ['Ekspresyonizm, dışavurumculuk', 'Kübizm, geometrik biçimler akımı', 'Dadaizm, anlamsızlık akımı'], 'Akımın adı Monet\'nin 1872 tarihli tablosunun başlığından türemiştir.'),
  ('Kendi aralarındaki farkları göz önünde bulundurarak sürrealizm ve realizm için aşağıdakilerden hangisi doğrudur?', 'Realizm gözleme, sürrealizm bilinçdışı ve düşlere dayanır.', ['İkisi de bilinçdışına dayanır.', 'İkisi de yalnız şiirde görülür.', 'Sürrealizm 19. yüzyılda, realizm 20. yüzyılda ortaya çıkmıştır.'], 'Realizm gözlemlenebilir toplumsal gerçekliğe, sürrealizm ise düş ve bilinçdışına yönelir.'),
  ('Eski el yazması eserlerde, istinsah edilen kitabın sonuna eklenen ve yazının kimin tarafından, hangi tarihte yazıldığını bildiren nota ne ad verilir?', 'Kolofon', ['Önsöz, giriş yazısı', 'Epigraf, başa konan alıntı', 'Dizin, adlar listesi'], 'Kolofon, el yazması metinlerde yazıcıya ve tarihe dair bilgi verir.'),
  ('Metni yazarından ve çevresinden bağımsız olarak, yalnız iç yapısıyla inceleyen ve \'yakın okuma\' yöntemini kullanan akım hangisidir?', 'Yeni Eleştiri', ['Biyografik eleştiri, yazarın hayatına dayanan yöntem', 'Marksist eleştiri, toplumsal sınıfa odaklanan yöntem', 'Psikanalitik eleştiri, bilinçdışına odaklanan yöntem'], 'Yeni Eleştiri, anlamı metnin kendi içinde arar.'),
  ('Wimsatt ve Beardsley\'nin \'kasıt yanılgısı\' kavramı neyi eleştirir?', 'Bir eserin anlamını yazarın niyetine bağlamayı', ['Bir eserin okur tarafından yorumlanmasını', 'Eserdeki sözcük seçiminin ahenk bakımından değerlendirilmesini', 'Eserin yayın tarihine göre değerlendirilmesini'], 'Kasıt yanılgısı, eserin anlamını yazarın niyetiyle sınırlamayı eleştirir.'),
  ('Roland Barthes\'ın \'Yazarın Ölümü\' denemesinde öne sürdüğü temel fikir nedir?', 'Metnin anlamı yazarın niyetiyle değil, okurun yorumuyla ortaya çıkar.', ['Yazarlar yazmayı bırakmalıdır.', 'Yazarın yaşamı eseri açıklayan en önemli veridir.', 'Yazarın eseri ölümünden sonra yayımlanmalıdır.'], 'Barthes, anlam üretiminin merkezine yazarı değil okuru koyar.'),
  ('Hans Robert Jauss\'un alımlama estetiğinde \'beklentiler ufku\' kavramı neyi anlatır?', 'Okurun metni okumadan önce sahip olduğu beklenti ve birikimi', ['Yazarın yazarken izlediği kuralları', 'Metnin sayfa düzenini', 'Metindeki mekân bilgisini'], 'Okurun önceki okuma birikimi, metni anlamlandırma çerçevesini oluşturur.'),
  ('Göstergebilimsel (semiyotik) bir okuma neyi inceler?', 'Metindeki göstergelerin anlam üretme biçimini', ['Yazarın doğum yerini', 'Kitabın basım sayısını', 'Metnin sayfa sayısını'], 'Göstergebilim, metinde göstergelerin anlam kurma düzenini inceler.'),
  ('Platon, sanatı \'gerçeğin gölgesinin gölgesi\' olarak niteleyerek nasıl bir görüş savunur?', 'Sanat, taklidin taklididir ve gerçeklikten uzaktır', ['Sanat, gerçeğin ta kendisidir', 'Sanat, bilimsel bilgidir', 'Sanat, tanrısal ilhamdır'], 'Platon\'a göre sanat, idealar dünyasının taklidi olan nesnelerin taklididir.'),
  ('Aristoteles, sanatın gerçekliği taklit etmesine Platon\'dan farklı olarak nasıl bakar?', 'Taklidi insan doğasının öğrenme biçimi olarak değerli bulur', ['Taklidi tamamen değersiz sayar', 'Taklidi yasaklar', 'Taklidin yalnız tiyatroda olmasını ister'], 'Aristoteles taklidi insanı öğrenmeye ve anlamaya götüren doğal bir etkinlik sayar.'),
  ('Bir ifadede kavramların derece derece yükseltilerek ya da alçaltılarak sıralanmasına ne ad verilir?', 'Tedric', ['Rücu, sözden dönme', 'Hüsnütalil, güzel nedene bağlama', 'Mübalağa, abartma'], 'Derece derece yükselen anlatım tedricdir.'),
  ('Bir şiirde Kur\'an ayeti ya da hadisten bir bölümün şiirin içine yerleştirilmesine ne ad verilir?', 'İktibas', ['Telmih, kısa gönderme', 'Tevriye, iki anlamlı söz', 'Tezat, karşıtlık'], 'Ayet ya da hadisten alıntı yapma iktibas sanatıdır.'),
  ('Coşkulu, yüceltici bir tonla bir kişi, olay ya da değeri öven ve Pindaros ile Horatius\'un da kullandığı şiir türü hangisidir?', 'Ode', ['Elegi, ağıt şiiri', 'Satir, alaycı şiir', 'Balad, öyküleyici şiir'], 'Övgü ve yüceltme amaçlı coşkulu şiir odedir.'),
  ('Baudelaire\'in \'Paris Sıkıntısı\'nda örneğini verdiği, şiirsel bir dille yazılmış ama dizelere bölünmeyen yazılara ne ad verilir?', 'Düzyazı şiir', ['Sone, on dört dizelik şiir', 'Haiku, üç dizelik şiir', 'Elegi, ağıt şiiri'], 'Dizesiz ama şiirsel yoğunlukta yazılan eser düzyazı şiirdir.'),
  ('Bir sanatçının sanat anlayışını, yöntemini ve ilkelerini açıkladığı yazılara ne ad verilir?', 'Poetika', ['Antoloji, seçki', 'Dizin, adlar listesi', 'Künye, yayın bilgisi'], 'Sanat anlayışının kuramsal biçimde açıklanması poetikadır.'),
  ('Bir dönemin değer yargılarıyla seçilip kalıcı kabul edilen ve okullarda okutulan eserler topluluğuna ne ad verilir?', 'Kanon', ['Manifesto, bildiri', 'Antoloji, seçki', 'Poetika, sanat anlayışı'], 'Edebiyat kanonu, değer verilen eserlerin oluşturduğu bütündür.'),
  ('İki öğrenci aynı öykü üzerinde tartışıyor. Birincisi \'Anlatıcı kahraman olduğuna göre anlattıkları kesin gerçektir\' diyor. İkincisi ise \'Kahraman bile olsa olayları kendi çıkarına göre aktarabilir\' diyor. Hangi görüş edebiyat kuramı açısından daha savunulabilirdir?', 'İkincisi; birinci kişi anlatıcı kendi bakışıyla sınırlıdır ve taraflı olabilir.', ['Birincisi; birinci kişi anlatıcı her zaman nesneldir.', 'Birincisi; çünkü kahraman olayları yaşamıştır ve yanılmaz.', 'İkisi de yanlıştır; çünkü anlatıcı yalnız yazarın sesidir.'], 'Birinci kişi anlatıcı yalnız kendi bakışını sunduğundan taraflı ve yanılabilir olabilir.'),
  ('Bir öyküde anlatıcı, olayların hemen ardından \'Bunu neden yaptığımı hâlâ bilmiyorum\' diyerek kendi davranışını sorguluyor. Bu sözün öykünün anlatı yapısına katkısı en çok hangisidir?', 'Anlatıcının sınırlı bilgisini göstererek okuru yoruma ortak etmesi', ['Olayın kronolojisini düzeltmesi', 'Mekânı daha net betimlemesi', 'Okura kesin ve tek bir hüküm vermesi'], 'Anlatıcının kendi eylemini anlamadığını itiraf etmesi, okuru yorum yapmaya davet eder.'),
  ('Bir romanın anlatıcısı sürekli \'Siz de bilirsiniz ki...\' diyerek okura seslenip onunla ortak bir değer dünyası varmış gibi davranıyor. Bu yöntemin etkisi nedir?', 'Okuru anlatıcının bakışına ortak ederek ikna etmeye çalışması', ['Okuru olaylardan uzaklaştırması', 'Anlatıcıyı gizlemesi', 'Zamanı belirsizleştirmesi'], 'Okura ortaklık atfetmek, anlatıcının görüşünü doğal gösterme yoludur.'),
  ('Aşağıdakilerden hangisi anlatıcının güvenilmez olabileceğine ilişkin bir ipucu sayılamaz?', 'Anlatıcının olayları kronolojik sırayla aktarması', ['Anlatıcının kendi sözleriyle çelişmesi', 'Başka kişilerin anlatıcının sözlerini yalanlaması ve düzeltmesi', 'Anlatıcının olayı kendi çıkarına göre yorumlaması'], 'Kronolojik anlatım güvenilirlikle doğrudan ilgili değildir; diğerleri güvensizlik işaretleridir.'),
  ('\'Lütfen sessiz olun.\' cümlesi Jakobson\'a göre hangi işlevi baskın olarak taşır?', 'Alıcıyı etkileme (çağrı) işlevi', ['Heyecan (duygusal) işlevi, konuşanın duygusunu aktarma', 'Göndergesel işlev, gerçek dünyaya ilişkin bilgi verme', 'Şiirsel işlev'], 'Alıcıdan bir davranış isteyen dil çağrı işlevinde kullanılmıştır.'),
  ('\'Ali yarın sabah altıda Ankara\'ya gidecek.\' cümlesinde baskın dil işlevi hangisidir?', 'Göndergesel işlev', ['Heyecan işlevi, konuşanın duygusunu aktarma', 'Şiirsel işlev', 'İlgi kurma işlevi'], 'Gerçek bir olay ya da durum hakkında bilgi veren dil göndergesel işlevdedir.'),
  ('Bir edebî metinde Jakobson\'a göre şiirsel işlevin baskın olması neyi gösterir?', 'Mesajın biçiminin, ses ve düzeninin ön plana çıktığını', ['Bilgi vermenin öncelik taşıdığını', 'Alıcıdan eylem beklendiğini', 'İletişim kanalının sınandığını'], 'Şiirsel işlev, mesajın biçimine odaklanmasıdır.'),
  ('Bir yazar, aynı olayı farklı bölümlerde farklı zamanlardan bakarak yeniden anlatıyor. Bu seçimin okura sağladığı en önemli şey nedir?', 'Aynı olayın farklı zaman ve bakışlarla yeni anlamlar kazanması', ['Olayların tek bir yoruma bağlanması', 'Olay sayısının azalması', 'Anlatıcının ortadan kalkması'], 'Aynı olayın yinelenmesi, olayın farklı yönlerini aydınlatır.'),
  ('\'Çocukken bu evde saklambaç oynardık\' cümlesiyle anlatıcı geçmişe döner. Aşağıdakilerden hangisi geriye dönüşün bir işlevi olamaz?', 'Okura kahramanın geleceğini kesin biçimde bildirmek', ['Kahramanın geçmişini ve çocukluğunu açıklamak', 'Bugünkü davranışlarının nedenini geçmişte göstermek', 'Atmosferi derinleştirip nostaljik bir hava kurmak'], 'Geriye dönüş geçmişe dairdir; geleceği bildirmek ileri sıçramanın işlevidir.'),
  ('Bir romanda kahraman, hem ailesinin beklentileriyle hem de kendi hayalleriyle çatışıyor. Bu durumda hangi iki çatışma türü bir aradadır?', 'İç çatışma ve birey–toplum (aile) çatışması', ['Birey–doğa ve birey–kader çatışması', 'Yalnız birey–birey çatışması, iki kişi arasındaki mücadele', 'Hiçbir çatışma yoktur, kahraman huzur içindedir'], 'Kendi hayalleriyle çatışma iç, ailenin beklentisiyle çatışma toplumsal çatışmadır.'),
  ('Epik tiyatroda seyircinin sahnedeki olaya duygusal olarak kapılması yerine ona eleştirel mesafeyle bakması amaçlanır. Aşağıdakilerden hangisi bu amaca hizmet eden bir uygulama olabilir?', 'Oyuncunun seyirciye doğrudan seslenmesi ve oyunun kurmaca olduğunu hatırlatması', ['Sahnede gerçekçi dekorun artırılması', 'Oyuncunun kişiyle tamamen özdeşleşmesi', 'Seyircinin karanlıkta oturup sessiz kalması'], 'Seyirciye doğrudan seslenme yabancılaştırma etkisi yaratır.'),
  ('Klasik trajedide kahraman genellikle soylu biridir; modern dramda ise sıradan insanlar öne çıkar. Bu değişim en çok neyi yansıtır?', 'Sanatın sıradan insanın yaşamına ve sorunlarına yönelmesini', ['Tiyatronun yok olmasını', 'Soylu kişilerin yok olmasını', 'Komedinin gerilemesini'], 'Sıradan kişilerin kahraman olması, sanatın gündelik hayata yönelişini gösterir.'),
  ('Absürt bir oyunda iki kişi sürekli birini beklemekte ama beklenen kişi hiç gelmemekte ve olaylar ilerlememektedir. Bu yapı oyunun hangi anlamını öne çıkarır?', 'İnsanın anlamsız bekleyiş ve boşluk karşısındaki durumunu', ['Kahramanın nihai zaferini', 'Komedinin mutlu sonunu', 'Tarihî bir olayın anlatımını'], 'Beklemenin boşuna oluşu, varoluşun anlamsızlığını sezdirir.'),
  ('Bir oyun yazarı, kahramanının iç dünyasını seyirciye aktarmak istiyor. Roman yazarında olduğu gibi anlatıcıyı kullanamadığı için hangi yolu seçebilir?', 'Monolog ve aparte', ['Betimleme paragrafları yazmak', 'Dipnot eklemek', 'Kitap önsözü yazmak'], 'Tiyatroda iç dünya monolog ve apartelerle seyirciye açılır.'),
  ('Aşağıdakilerden hangisi tarihî romanın özelliklerinden biri değildir?', 'Anlatıcının sürekli geleceğe bakarak bilimsel buluşları anlatması', ['Gerçek tarihî olayların kurguya katılması', 'Dönemin atmosferinin yansıtılması', 'Gerçek ya da gerçeğe benzer tarihî kişilerin yer alması'], 'Gelecek ve bilimsel buluş anlatımı bilimkurgunun özelliğidir.'),
  ('Aşağıdakilerden hangisi gerçekçi romanın özelliklerinden değildir?', 'Olağanüstü olayların gerçeklikmiş gibi sunulması', ['Gözlemlere dayalı betimlemeler', 'Toplumsal ilişkilerin yansıtılması', 'Kişilerin inandırıcılığı'], 'Olağanüstü olaylar gerçekçi romandan çok fantastik anlatıya özgüdür.'),
  ('Peirce\'ün gösterge sınıflamasında, gösterdiği şeye benzerlik yoluyla gönderme yapan göstergeye ne ad verilir?', 'İkon', ['İndeks, nedensel ilişki taşıyan gösterge', 'Simge, toplumsal uzlaşıya dayanan gösterge', 'Gösteren, göstergenin ses biçimi'], 'İkon, gösterdiği şeye benzerlik temelinde anlam kazanan göstergedir.'),
  ('Peirce\'e göre dumanın ateşi göstermesi ve ayak izinin geçeni göstermesi hangi gösterge türüne örnektir?', 'İndeks', ['İkon, benzerlik yoluyla gösterge', 'Simge, uzlaşı yoluyla gösterge', 'Gönderge, nesnenin kendisi'], 'Doğal bir bağ ya da neden–sonuç ilişkisiyle gönderme yapan gösterge indekstir.'),
  ('Peirce\'ün simge (sembol) tanımına göre simgenin göstergesi ile gösterdiği şey arasında bağ nasıl kurulur?', 'Toplumsal uzlaşı yoluyla', ['Fiziksel benzerlik yoluyla', 'Doğal neden–sonuç yoluyla', 'Rastlantı yoluyla'], 'Simgede ilişki doğal değildir, toplumsal uzlaşıya dayanır.'),
  ('\'Sabır, acı bir ilaçtır ama şifası tatlıdır.\' cümlesinde hangi söz sanatı kullanılmıştır?', 'Teşbih-i beliğ ve tezat', ['Yalnız mübalağa, çünkü sabır abartılarak anlatılmıştır', 'Yalnız hüsnütalil, çünkü güzel bir nedene bağlanmıştır', 'Yalnız tenasüp, çünkü anlamca ilişkili sözcükler kullanılmıştır'], 'Sabır ile ilaç benzetilmiş (beliğ), acı–tatlı da karşıtlık oluşturmuştur.'),
  ('\'Ufkun kırmızı dudakları güneşi öptü.\' dizesinde hangi söz sanatları bir aradadır?', 'Kapalı istiare ve teşhis', ['Açık istiare ve tezat, çünkü benzetilen söylenmiş ve karşıtlık vardır', 'Kinaye ve mübalağa, çünkü dolaylı anlatım ile abartı bir aradadır', 'Hüsnütalil ve cinas, çünkü güzel neden ve sesteş sözcük vardır'], 'Ufuk dudaklı bir insana benzetilip öpme eylemi yapıyor; benzetilen söylenmeyen kapalı istiare ve teşhis vardır.'),
  ('\'Bu kadar kalabalıkta bile elimden tutan olmadı.\' cümlesindeki \'elimden tutmak\' sözü hangi kullanımdadır?', 'Yardım etmek anlamında mecazlı, kinayeli kullanım', ['Terim anlamlı kullanım, çünkü bilim diline özgü bir sözdür', 'Düz anlamlı kullanım, çünkü gerçekten bir elin tutulması anlatılır', 'Cinaslı kullanım, çünkü sesteş iki sözcük bir arada kullanılmıştır'], 'Gerçek anlamı da düşündüren ama asıl \'yardım etmek\' anlamının kastedildiği kinayeli bir kullanımdır.'),
  ('\'Dil, bir halkın hafızasıdır. Bir dilin sözcükleri, o halkın yüzyıllar boyunca yaşadıklarının tortusudur.\' Bu parçada \'hafıza\' sözcüğünün kullanımı hangi söz sanatını akla getirir?', 'Teşbih-i beliğ ya da istiare niteliğinde benzetme', ['Cinas, sesteş sözcüklerin söz oyunu için kullanılması', 'Tevriye, iki anlamlı sözcüğün uzak anlamının kastedilmesi', 'Hüsnütalil, bir olayın güzel bir nedene bağlanması'], 'Dilin hafızaya benzetilmesi benzetme sanatıdır.'),
  ('\'Kasaba küçüktü; herkes herkesi tanır, kim ne zaman uyanır, kim ne zaman uyur bilirdi. Ve tam da bu yüzden, kimse kimseyi gerçekten görmezdi.\' Son cümle parçanın anlatısında hangi etkiyi yaratır?', 'Paradoksal bir vurguyla yalnızlığı ve görünmezliği sezdirir.', ['Kasabanın nüfusunu ve büyüklüğünü kesin rakamlarla verir.', 'Olayların zamanını ve geçtiği mevsimi açıkça belirler.', 'Anlatıcının kimliğini gizleyerek okuru yanıltmayı amaçlar.'], 'Herkesi tanıyıp kimseyi görmemek paradoks olup yabancılaşmayı sezdirir.'),
  ('\'Yazmak, boş bir odaya ışık getirmektir; ama ışık, bazen odanın bilmediğin köşelerini de gösterir.\' Bu cümleyle yazarın anlatmak istediği nedir?', 'Yazmak, kişiye kendi bilmediği yönlerini de gösterebilir.', ['Odalar her zaman karanlıktır ve ışık yalnızca bir eşyadır.', 'Işık ucuzdur, bu nedenle yazı da ucuz bir uğraştır.', 'Yazmak kolaydır; her kişi hiç düşünmeden aynı sonuca ulaşır.'], 'Işık benzetmesi, yazının aynı zamanda kişiye kendini tanıttığını sezdirir.'),
];
